import re, sys
src, dst, cls = sys.argv[1], sys.argv[2], sys.argv[3]
t = open(src, encoding='utf-8').read()
t = t.replace('package com.cax.pmk.emulator;', '')
t = re.sub(r'public class (\w+)\s*\{', r'public static class \1\n{', t, count=1)
t = re.sub(r'public static final int\s*\[\]\s*', 'public static readonly int[] ', t)
hdr = ("// EmulatorMK61 - ROM tables of the K745IK13 chips, from pmk-android (xvadim/pmk-android,\n"
       "// itself after Felix Lazarev's emu145). GPL-3.0, see LICENSE. Generated by tools/rom2cs.py.\n"
       "namespace EmulatorMK61.Core\n{\n")
open(dst, 'w', encoding='utf-8', newline='\r\n').write(hdr + t.strip() + "\n}\n")
